import sys, json
import pandas as pd
sys.path.insert(0, '/app/categorizationapp')
from categorizationapp.UtilityScripts.AppUtil import clean_input_df

def run(bank_fn, rows, accountType="SAVING", accountHolder=None):
    df = pd.json_normalize(rows)
    for c in ['remark', 'description']:
        if c not in df:
            df[c] = ""
    if 'balanceAfterTransaction' not in df:
        df['balanceAfterTransaction'] = 1000
    df = clean_input_df(df)
    import inspect
    n = len(inspect.signature(bank_fn).parameters)
    if n == 3:
        out = bank_fn(df, accountType, accountHolder or "SELF")
    else:
        out = bank_fn(df, accountType)
    return out[['description', 'remark', 'type', 'amount', 'transactionCategory', 'transactionSubcategory', 'partyName']]

def show(x):
    pd.set_option('display.width', 250)
    pd.set_option('display.max_colwidth', 60)
    print(x.to_string())

