import re, glob, os, sys, importlib
sys.path.insert(0,'.')
import categorizationapp.UtilityScripts.BankRegexConstants as B
import categorizationapp.UtilityScripts.RegexConstants as R
consts = {}
for m in (B,R):
    for k,v in vars(m).items():
        if isinstance(v,str) and not k.startswith('_'): consts[k]=v

pat_call = re.compile(r'py_extract\(\s*([^,]+),\s*(?:pat=)?(.+?),\s*index=(\d+)\s*\)')
for f in sorted(glob.glob('categorizationapp/**/*.py', recursive=True)):
    src = open(f).read().split('\n')
    for i,line in enumerate(src,1):
        for m in pat_call.finditer(line):
            patexpr, idx = m.group(2).strip(), int(m.group(3))
            p = None
            if patexpr.startswith(('"',"'")) and patexpr.endswith(('"',"'")):
                p = patexpr[1:-1].encode().decode('unicode_escape')
            elif patexpr in consts:
                p = consts[patexpr]
            if p is None: continue
            try: n = re.compile(p).groups
            except Exception as e: print("ERRPAT",f,i,e); continue
            if idx >= n:
                print(f"OUT-OF-RANGE {f}:{i} index={idx} groups={n} pat={p!r}")
EOF

cd /app/categorizationapp/categorizationapp && python3 - <<'EOF'
import re, glob
# find rules with contradictory same-column comparisons or type mismatches
for f in sorted(glob.glob('BankScripts/*.py')+glob.glob('UtilityScripts/*.py')):
    for i,line in enumerate(open(f).read().split('\n'),1):
        s=line.strip()
        if not s.startswith('['): continue
        # contradictory type
        if 'type.eq("DEBIT")' in s and 'type.eq("CREDIT")' in s and 'shift' not in s:
            print(f"CONTRA-TYPE {f}:{i}")
        # duplicate identical condition fragments
        for pat in re.findall(r'transactions\.\w+\.eq\("[A-Z_]+"\)', s):
            if s.count(pat)>1: print(f"DUP-COND {f}:{i} {pat}")
        # amount eq two different values
        eqs = re.findall(r'amount\.eq\(([0-9.]+)\)', s)
        if len(set(eqs))>1: print(f"CONTRA-AMT {f}:{i} {eqs}")
        # amount lt/gt contradiction
        lt = re.findall(r'amount\.l[te]\(([0-9.]+)\)', s); gt = re.findall(r'amount\.g[te]\(([0-9.]+)\)', s)
        if lt and gt and min(map(float,lt)) <= min(map(float,gt)): print(f"CONTRA-RANGE {f}:{i} lt={lt} gt={gt}")
        # str comparisons with numbers on string cols
        if re.search(r'(remark|description|partyName|party2)\.(eq|isin)\(\[?[0-9]', s): print(f"NUM-ON-STR {f}:{i}")
        # len().eq(N) with regex longer
        m = re.search(r'(\w+)\.str\.len\(\)\.eq\((\d+)\)', s)
        if m:
            n=int(m.group(2))
            for pat in re.findall(r'"(\^[^"]+)"', s):
                lo = 0
                for tok in re.finditer(r'\{(\d+)(,(\d+)?)?\}', pat): lo += int(tok.group(1))-1
                lo += len(re.sub(r'\\.|\{\d+(,\d*)?\}|[\^\$\[\]\(\)\|\*\+\?]', '', pat))
                print(f"LEN-CHECK {f}:{i} len={n} pat={pat} minlen~{lo}")
EOF

